21	class GXMMeshStorage : public RendererDummy::MeshStorage {
22	    struct Skeleton {
23	        Vector<Transform3D> bones;
24	        Dependency dependency;
25	        uint64_t version = 1;
26	    };
27	    mutable RID_Owner<Skeleton> skeletons;
28	    HashMap<RID, HashMap<int, Array>> decoded;
29	    // Bound CPU cache independently from the loader's CDRAM texture budget.
30	    uint64_t cache_bytes = 0;
31	public:
32	    // Static geometry flattened once. `gpu` lives in the bridge's mapped
33	    // arena and is drawn without per-frame vertex conversion; xyz/uv are
34	    // only kept when the arena is full or unavailable (CPU fallback).
35	    struct FlatSurface {
36	        void *gpu = nullptr;
37	        unsigned count = 0;
38	        Vector<float> xyz, uv;
39	        // Local positions and normals in the same flattened order, kept only
40	        // for surfaces that receive per-vertex lighting.
41	        Vector<Vector3> positions, normals;
42	    };
43	    struct SurfaceInfo {
44	        bool triangles = false;
45	        unsigned triangle_count = 0;
46	        RID material;
47	    };
48	    struct MeshInfo {
49	        Vector<SurfaceInfo> surfaces;
50	        unsigned triangle_count = 0;
51	    };
52	    unsigned invalidations = 0;
53	    bool arena_exhausted = false;
54	private:
55	    HashMap<RID, HashMap<int, FlatSurface>> flat;
56	    HashMap<RID, MeshInfo> info;
57	    uint64_t flat_bytes = 0;
58	public:
59	    // Cached per-mesh metadata: mesh_get_surface() copies the whole
60	    // SurfaceData, which is too expensive to do per surface per frame.
61	    const MeshInfo &get_info(RID rid) {
62	        MeshInfo *cached = info.getptr(rid);
63	        if (cached) return *cached;
64	        MeshInfo value;
65	        int count = mesh_get_surface_count(rid);
66	        value.surfaces.resize(count);
67	        for (int s = 0; s < count; s++) {
68	            auto surface = mesh_get_surface(rid, s);
69	            SurfaceInfo &entry = value.surfaces.write[s];
70	            entry.triangles = surface.primitive == RSE::PRIMITIVE_TRIANGLES;
71	            entry.triangle_count = entry.triangles ? unsigned(surface.index_count ? surface.index_count : surface.vertex_count) / 3 : 0;
72	            entry.material = surface.material;
73	            value.triangle_count += entry.triangle_count;
74	        }
75	        return info.insert(rid, value)->value;
76	    }
77	    const FlatSurface *get_flat(RID rid, int surface, const PackedVector3Array &positions, const PackedVector2Array &uvs, const PackedInt32Array &indices) {
78	        auto *entry = flat.getptr(rid);
79	        if (entry && entry->has(surface)) return &(*entry)[surface];
80	        int count = indices.is_empty() ? positions.size() : indices.size();
81	        count -= count % 3;
82	        if (!count) return nullptr;
83	        Vector<float> xyz, uv;
84	        xyz.resize(count * 3);
85	        uv.resize(count * 2);
86	        float *xyz_w = xyz.ptrw();
87	        float *uv_w = uv.ptrw();
88	        const Vector3 *source = positions.ptr();
89	        const Vector2 *source_uv = uvs.ptr();
90	        const int32_t *source_index = indices.ptr();
91	        for (int i = 0; i < count; i++) {
92	            int vertex = indices.is_empty() ? i : source_index[i];
93	            if (vertex < 0 || vertex >= positions.size()) return nullptr;
94	            xyz_w[i * 3] = source[vertex].x;
95	            xyz_w[i * 3 + 1] = source[vertex].y;
96	            xyz_w[i * 3 + 2] = source[vertex].z;
97	            uv_w[i * 2] = vertex < uvs.size() ? source_uv[vertex].x : 0;
98	            uv_w[i * 2 + 1] = vertex < uvs.size() ? source_uv[vertex].y : 0;
99	        }
100	        FlatSurface value;
101	        value.count = count;
102	        value.gpu = vita_gxm_mesh_create(xyz.ptr(), uv.ptr(), count);
103	        if (!value.gpu && vita_gxm_mesh_arena_used() > 0) arena_exhausted = true;
104	        if (!value.gpu) {
105	            uint64_t bytes = uint64_t(count) * 5 * sizeof(float);
106	            if (flat_bytes + bytes > 32 * 1024 * 1024) return nullptr;
107	            value.xyz = xyz;
108	            value.uv = uv;
109	            flat_bytes += bytes;
110	        }
111	        flat[rid][surface] = value;
112	        return &flat[rid][surface];
113	    }
114	    const FlatSurface *get_flat_geometry(RID rid, int surface) {
115	        auto *entry = flat.getptr(rid);
116	        FlatSurface *value = entry ? entry->getptr(surface) : nullptr;
117	        if (!value) return nullptr;
118	        if (!value->positions.is_empty()) return value;
119	        Array arrays = get_decoded(rid, surface);
120	        if (arrays.is_empty()) return nullptr;
121	        PackedVector3Array positions = arrays[RSE::ARRAY_VERTEX];
122	        PackedVector3Array normals = arrays[RSE::ARRAY_NORMAL];
123	        PackedInt32Array indices = arrays[RSE::ARRAY_INDEX];
124	        int count = indices.is_empty() ? positions.size() : indices.size();
125	        count -= count % 3;
126	        if (unsigned(count) != value->count) return nullptr;
127	        value->positions.resize(count);
128	        value->normals.resize(normals.size() == positions.size() ? count : 0);
129	        Vector3 *out_p = value->positions.ptrw();
130	        Vector3 *out_n = value->normals.is_empty() ? nullptr : value->normals.ptrw();
131	        for (int i = 0; i < count; i++) {
132	            int vertex = indices.is_empty() ? i : indices[i];
133	            if (vertex < 0 || vertex >= positions.size()) vertex = 0;
134	            out_p[i] = positions[vertex];
135	            if (out_n) out_n[i] = normals[vertex];
136	        }
137	        flat_bytes += uint64_t(count) * 24;
138	        return value;
139	    }
140	    bool owns_skeleton(RID rid) const { return skeletons.owns(rid); }
141	    uint64_t skeleton_version(RID rid) const {
142	        const Skeleton *s = skeletons.get_or_null(rid);
143	        return s ? s->version : 0;
144	    }
145	    const Vector<Transform3D> *skeleton_bones(RID rid) const {
146	        const Skeleton *s = skeletons.get_or_null(rid);
147	        return s ? &s->bones : nullptr;
148	    }
149	    RID skeleton_allocate() override { return skeletons.allocate_rid(); }
150	    void skeleton_initialize(RID rid) override { skeletons.initialize_rid(rid); }
151	    void skeleton_allocate_data(RID rid, int count, bool is_2d = false) override {
152	        Skeleton *s = skeletons.get_or_null(rid);
153	        ERR_FAIL_NULL(s);
154	        ERR_FAIL_COND(count < 0 || is_2d);
155	        s->bones.resize(count);
156	        s->dependency.changed_notify(Dependency::DEPENDENCY_CHANGED_SKELETON_DATA);
157	    }
158	    int skeleton_get_bone_count(RID rid) const override {
159	        const Skeleton *s = skeletons.get_or_null(rid);
160	        return s ? s->bones.size() : 0;
161	    }
162	    void skeleton_bone_set_transform(RID rid, int bone, const Transform3D &transform) override {
163	        Skeleton *s = skeletons.get_or_null(rid);
164	        ERR_FAIL_NULL(s);
165	        ERR_FAIL_INDEX(bone, s->bones.size());
166	        s->bones.write[bone] = transform;
167	        s->version++;
168	        s->dependency.changed_notify(Dependency::DEPENDENCY_CHANGED_SKELETON_BONES);
169	    }
170	    Transform3D skeleton_bone_get_transform(RID rid, int bone) const override {
171	        const Skeleton *s = skeletons.get_or_null(rid);
172	        return s && bone >= 0 && bone < s->bones.size() ? s->bones[bone] : Transform3D();
173	    }
174	    void skeleton_update_dependency(RID rid, DependencyTracker *tracker) override {
175	        Skeleton *s = skeletons.get_or_null(rid);
176	        if (s) tracker->update_dependency(&s->dependency);
177	    }
178	    void skeleton_free(RID rid) override {
179	        Skeleton *s = skeletons.get_or_null(rid);
180	        ERR_FAIL_NULL(s);
181	        s->dependency.deleted_notify(rid);
182	        skeletons.free(rid);
183	    }
184	    // Only the changed mesh is dropped. Clearing every cache on each mesh
185	    // change re-decoded the whole level whenever a script touched one mesh.
186	    // GPU arena space of a dropped mesh is reclaimed when the arena fills.
187	    void invalidate_mesh(RID rid) {
188	        invalidations++;
189	        auto *mesh = decoded.getptr(rid);
190	        if (mesh) {
191	            for (const KeyValue<int, Array> &surface : *mesh) {
192	                PackedVector3Array positions = surface.value.is_empty() ? PackedVector3Array() : PackedVector3Array(surface.value[RSE::ARRAY_VERTEX]);
193	                uint64_t bytes = uint64_t(positions.size()) * 256 + uint64_t(PackedInt32Array(surface.value[RSE::ARRAY_INDEX]).size()) * 4;
194	                cache_bytes = cache_bytes > bytes ? cache_bytes - bytes : 0;
195	            }
196	            decoded.erase(rid);
197	        }
198	        auto *surfaces = flat.getptr(rid);
199	        if (surfaces) {
200	            for (const KeyValue<int, FlatSurface> &surface : *surfaces) {
201	                uint64_t bytes = uint64_t(surface.value.xyz.size() + surface.value.uv.size()) * sizeof(float);
202	                flat_bytes = flat_bytes > bytes ? flat_bytes - bytes : 0;
203	            }
204	            flat.erase(rid);
205	        }
206	        info.erase(rid);
207	    }
208	    // Called when the GPU arena is full: rebuild resident geometry lazily.
209	    void reset_gpu_geometry() {
210	        flat.clear();
211	        flat_bytes = 0;
212	        arena_exhausted = false;
213	        vita_gxm_mesh_reset();
214	    }
215	    void mesh_free(RID rid) override { invalidate_mesh(rid); RendererDummy::MeshStorage::mesh_free(rid); }
216	    void mesh_clear(RID rid) override { invalidate_mesh(rid); RendererDummy::MeshStorage::mesh_clear(rid); }
217	    void mesh_surface_remove(RID rid, int surface) override { invalidate_mesh(rid); RendererDummy::MeshStorage::mesh_surface_remove(rid, surface); }
218	    void mesh_add_surface(RID rid, const RenderingServerTypes::SurfaceData &surface) override {
219	        invalidate_mesh(rid);
220	        RendererDummy::MeshStorage::mesh_add_surface(rid, surface);
221	    }
222	    Array get_decoded(RID rid, int surface) {
223	        auto *mesh = decoded.getptr(rid);
224	        if (mesh) {
225	            Array *cached = mesh->getptr(surface);
226	            if (cached) return *cached;
227	        }
228	        Array arrays = RenderingServer::get_singleton()->mesh_create_arrays_from_surface_data(mesh_get_surface(rid, surface));
229	        if (arrays.is_empty()) return arrays;
230	        // Account by vertex count conservatively; avoid dynamic Variant property lookups.
231	        PackedVector3Array positions = arrays.is_empty() ? PackedVector3Array() : PackedVector3Array(arrays[RSE::ARRAY_VERTEX]);
232	        uint64_t bytes = uint64_t(positions.size()) * 256 + uint64_t(PackedInt32Array(arrays[RSE::ARRAY_INDEX]).size()) * 4;
233	        if (cache_bytes + bytes <= 32 * 1024 * 1024) { decoded[rid][surface] = arrays; cache_bytes += bytes; }
234	        return arrays;
235	    }
236	    AABB mesh_get_aabb(RID rid, RID skeleton = RID()) override {
237	        AABB bounds;
238	        int count = mesh_get_surface_count(rid);
239	        for (int i = 0; i < count; i++) {
240	            AABB next = mesh_get_surface(rid, i).aabb;
241	            auto surface = mesh_get_surface(rid, i);
242	            if (owns_skeleton(skeleton)) {
243	                for (int bone = 0; bone < surface.bone_aabbs.size() && bone < skeleton_get_bone_count(skeleton); bone++) {
244	                    if (surface.bone_aabbs[bone].size != Vector3()) {
245	                        next = next.merge(skeleton_bone_get_transform(skeleton, bone).xform(surface.bone_aabbs[bone]));
246	                    }
247	                }
248	            }
249	            bounds = i == 0 ? next : bounds.merge(next);
250	        }
251	        return bounds;
252	    }
253	};
