255	// Keeps the light parameters the renderer needs for its per-object lighting
256	// approximation. Shadows, projectors and light baking remain unsupported.
257	class GXMLightStorage : public RendererDummy::LightStorage {
258	public:
259	    struct Light {
260	        RSE::LightType type = RSE::LIGHT_OMNI;
261	        Color color = Color(1, 1, 1);
262	        float params[RSE::LIGHT_PARAM_MAX] = {};
263	        uint32_t cull_mask = 0xFFFFFFFF;
264	        bool negative = false;
265	        uint64_t version = 0;
266	    };
267	    struct LightInstance {
268	        RID light;
269	        Transform3D transform;
270	    };
271	private:
272	    mutable RID_Owner<Light, true> lights;
273	    mutable RID_Owner<LightInstance> light_instances;
274	    RID allocate(RSE::LightType type) {
275	        Light light;
276	        light.type = type;
277	        light.params[RSE::LIGHT_PARAM_ENERGY] = 1.0f;
278	        light.params[RSE::LIGHT_PARAM_INDIRECT_ENERGY] = 1.0f;
279	        light.params[RSE::LIGHT_PARAM_RANGE] = 5.0f;
280	        light.params[RSE::LIGHT_PARAM_ATTENUATION] = 1.0f;
281	        light.params[RSE::LIGHT_PARAM_SPOT_ANGLE] = 45.0f;
282	        light.params[RSE::LIGHT_PARAM_SPOT_ATTENUATION] = 1.0f;
283	        return lights.make_rid(light);
284	    }
285	public:
286	    bool owns_light(RID rid) const { return lights.owns(rid); }
287	    const Light *get_light(RID rid) const { return lights.get_or_null(rid); }
288	    const LightInstance *get_light_instance(RID rid) const { return light_instances.get_or_null(rid); }
289	
290	    RID directional_light_allocate() override { return allocate(RSE::LIGHT_DIRECTIONAL); }
291	    void directional_light_initialize(RID) override {}
292	    RID omni_light_allocate() override { return allocate(RSE::LIGHT_OMNI); }
293	    void omni_light_initialize(RID) override {}
294	    RID spot_light_allocate() override { return allocate(RSE::LIGHT_SPOT); }
295	    void spot_light_initialize(RID) override {}
296	    void light_free(RID rid) override {
297	        if (lights.owns(rid)) lights.free(rid);
298	    }
299	    void light_set_color(RID rid, const Color &color) override {
300	        Light *light = lights.get_or_null(rid);
301	        if (light) { light->color = color; light->version++; }
302	    }
303	    void light_set_param(RID rid, RSE::LightParam param, float value) override {
304	        Light *light = lights.get_or_null(rid);
305	        ERR_FAIL_INDEX(param, RSE::LIGHT_PARAM_MAX);
306	        if (light) { light->params[param] = value; light->version++; }
307	    }
308	    void light_set_negative(RID rid, bool enable) override {
309	        Light *light = lights.get_or_null(rid);
310	        if (light) light->negative = enable;
311	    }
312	    void light_set_cull_mask(RID rid, uint32_t mask) override {
313	        Light *light = lights.get_or_null(rid);
314	        if (light) light->cull_mask = mask;
315	    }
316	    RSE::LightType light_get_type(RID rid) const override {
317	        const Light *light = lights.get_or_null(rid);
318	        return light ? light->type : RSE::LIGHT_OMNI;
319	    }
320	    AABB light_get_aabb(RID rid) const override {
321	        const Light *light = lights.get_or_null(rid);
322	        if (!light) return AABB();
323	        float range = light->params[RSE::LIGHT_PARAM_RANGE];
324	        if (light->type == RSE::LIGHT_OMNI) return AABB(Vector3(-range, -range, -range), Vector3(range, range, range) * 2);
325	        if (light->type == RSE::LIGHT_SPOT) {
326	            float size = Math::tan(Math::deg_to_rad(MIN(light->params[RSE::LIGHT_PARAM_SPOT_ANGLE], 89.0f))) * range;
327	            return AABB(Vector3(-size, -size, -range), Vector3(size * 2, size * 2, range));
328	        }
329	        return AABB();
330	    }

