 4	// The engine has already rejected objects outside the camera frustum. This
 5	// second stage removes geometry too small to matter on the Vita's 960x544
 6	// display while keeping nearby objects and large room structure.
 7	// Objects drawn in the previous frame use slightly wider limits, so an object
 8	// sitting on a threshold does not alternate between visible and culled.
 9	static inline bool should_cull(float center_distance, float radius, bool was_drawn = false) {
10	    if (center_distance < 0.001f) return false;
11	    const float edge_distance = center_distance - radius;
