91	/* Adds 6 freshly allocated vertices to the open batch or starts a new one. */
92	static void batch_append(int kind, GXMTexture *t, int linear, uint32_t color, void *vertices, size_t vertex_size) {
93	    stat_quads++;
94	    if (batch_count && batch_kind == kind && batch_count + 6 <= BATCH_MAX_VERTICES &&
95	            (uint8_t *)batch_start + (size_t)batch_count * vertex_size == (uint8_t *)vertices &&
96	            (kind == BATCH_COLOR || (batch_texture == t && batch_linear == linear && batch_color == color))) {
97	        batch_count += 6;
98	        return;
99	    }
100	    flush_batch();
101	    batch_kind = kind;
102	    batch_texture = t;
103	    batch_linear = linear;
104	    batch_color = color;
105	    batch_start = vertices;
106	    batch_count = 6;
107	}
