109	static void log_free_memory(const char *stage) {
110	    SceKernelFreeMemorySizeInfo info = { 0 };
111	    info.size = sizeof(info);
112	    int result = sceKernelGetFreeMemorySize(&info);
113	    fprintf(stderr, "[vita-memory] stage=%s result=0x%08x user_free=%u cdram_free=%u phycont_free=%u textures=%lu\n",
114	            stage, (unsigned int)result, info.size_user, info.size_cdram,
115	            info.size_phycont, (unsigned long)texture_bytes);
116	    fflush(stderr);
117	}
