119	static void destroy_texture(GXMTexture *t) {
120	    vita2d_free_texture(t->texture);
121	    texture_bytes -= t->bytes;
122	    free(t);
123	}
124	void *vita_gxm_texture_create(int width, int height, const uint8_t *rgba) {
125	    if (!initialized || !rgba || width < 1 || height < 1 || width > 4096 || height > 4096) return NULL;
126	    /* CDRAM allocations are rounded to 256 KiB, including tiny font atlases. */
127	    size_t bytes = vita_texture_allocation_bytes(width, height, texture_rgba4444 ? 2 : 4);
128	    if (bytes > 64 * 1024 * 1024 || texture_bytes > 64 * 1024 * 1024 - bytes) return NULL;
129	    GXMTexture *t = calloc(1, sizeof(*t));
130	    if (!t) return NULL;
131	    t->texture = vita2d_create_empty_texture_format(width, height,
132	            texture_rgba4444 ? SCE_GXM_TEXTURE_FORMAT_U4U4U4U4_ABGR : SCE_GXM_TEXTURE_FORMAT_A8B8G8R8);
133	    if (!t->texture) { free(t); return NULL; }
134	    uint8_t *data = vita2d_texture_get_datap(t->texture);
135	    unsigned stride = vita2d_texture_get_stride(t->texture);
136	    for (int y = 0; y < height; y++) {
137	        const uint8_t *source = rgba + (size_t)y * width * 4;
138	        if (texture_rgba4444) {
139	            uint16_t *destination = (uint16_t *)(data + (size_t)y * stride);
140	            for (int x = 0; x < width; x++) destination[x] = vita_pack_rgba4444(source + x * 4);
141	        } else {
142	            memcpy(data + (size_t)y * stride, source, (size_t)width * 4);
143	        }
144	    }
145	    t->bytes = bytes;
146	    texture_bytes += bytes;
147	    texture_upload_count++;
148	    if (texture_upload_count <= 16 || texture_upload_count % 128 == 0) {
149	        fprintf(stderr, "[gxm2d] texture uploads=%u last=%dx%d format=%s allocation=%lu budget=%lu\n", texture_upload_count, width, height,
150	                texture_rgba4444 ? "RGBA4444" : "RGBA8888", (unsigned long)bytes, (unsigned long)texture_bytes);
151	        fflush(stderr);
152	    }
153	    return t;
154	}
155	void vita_gxm_texture_free(void *texture) {
156	    GXMTexture *t = texture;
157	    if (!t) return;
158	    if (drawing || target_drawing || gpu_pending) {
159	        t->next = retired;
160	        retired = t;
161	    } else {
162	        destroy_texture(t);
163	    }
164	}
165	void vita_gxm_texture_quad(void *texture, const float *xy, const float *uv, uint32_t color, int linear) {
166	    GXMTexture *t = texture;
167	    if (!(drawing || target_drawing) || !t) return;
168	    vita2d_texture_vertex *v = vita2d_pool_memalign(6 * sizeof(*v), 8);
169	    if (!v) return;
170	    const int corners[6] = {0, 1, 2, 0, 2, 3};
171	    for (int i = 0; i < 6; i++) {
172	        int k = corners[i];
173	        v[i].x = xy[2 * k]; v[i].y = xy[2 * k + 1]; v[i].z = 0.5f;
174	        v[i].u = uv[2 * k]; v[i].v = uv[2 * k + 1];
175	    }
176	    batch_append(BATCH_TEXTURED, t, linear, color, v, sizeof(*v));
177	}
178	int vita_gxm_init(void) {
179	    if (initialized) return 1;
180	    FILE *scene_file = fopen("app0:gxm3d.cfg", "rb");
181	    scene3d_enabled = scene_file != NULL;
182	    if (scene_file) fclose(scene_file);
183	    /* Old packages without a format marker retain their original quality. */
184	    texture_rgba4444 = 0;
185	    FILE *format_file = fopen("app0:gxm_texture_format.cfg", "rb");
186	    if (format_file) {
187	        char format[32] = {0};
188	        if (fgets(format, sizeof(format), format_file)) texture_rgba4444 = strcmp(format, "RGBA4444\n") == 0;
189	        fclose(format_file);
190	    }
191	    /* 2D games also emit thousands of tile and glyph quads per frame; the
192	     * default 1 MiB vertex pool silently drops draws past ~8k quads. */
193	    int result = vita2d_init_advanced(4 * 1024 * 1024);
194	    fprintf(stderr, "[gxm2d] vita2d_init=%d texture_format=%s\n", result,
195	            texture_rgba4444 ? "RGBA4444" : "RGBA8888");
196	    fflush(stderr);
197	    initialized = result > 0;
198	    log_free_memory("renderer_init");
199	    return initialized;
200	}
201	void vita_gxm_begin(uint32_t color) {
202	    if (!initialized || drawing) return;
203	    if ((memory_frame++ % 600) == 0) log_free_memory("frame");
204	    wait_gpu();
205	    /* Not vita2d_start_drawing(): it resets the vertex pool, which an
206	     * offscreen scene earlier in this frame may still be reading. The pool
207	     * is reset by wait_gpu() once the previous frame is done. */
208	    vita2d_start_drawing_advanced(NULL, target_dependency ? SCE_GXM_SCENE_VERTEX_WAIT_FOR_DEPENDENCY : 0);
209	    target_dependency = 0;
210	    vita2d_disable_clipping();
211	    clip_enabled_cache = 0;
212	    vita2d_set_clear_color(color);
213	    SceGxmContext *ctx = vita2d_get_context();
214	    sceGxmSetViewport(ctx, 480.0f, 480.0f, 272.0f, -272.0f, 0.5f, 0.5f);
215	    if (scene3d_enabled) {
216	        sceGxmSetFrontDepthFunc(ctx, SCE_GXM_DEPTH_FUNC_ALWAYS);
217	        sceGxmSetBackDepthFunc(ctx, SCE_GXM_DEPTH_FUNC_ALWAYS);
218	        sceGxmSetFrontDepthWriteEnable(ctx, SCE_GXM_DEPTH_WRITE_ENABLED);
219	        sceGxmSetBackDepthWriteEnable(ctx, SCE_GXM_DEPTH_WRITE_ENABLED);
220	    }
221	    vita2d_clear_screen();
222	    if (scene3d_enabled) {
223	        sceGxmSetFrontDepthWriteEnable(ctx, SCE_GXM_DEPTH_WRITE_DISABLED);
224	        sceGxmSetBackDepthWriteEnable(ctx, SCE_GXM_DEPTH_WRITE_DISABLED);
225	    }
226	    drawing = 1;
227	}
228	void vita_gxm_quad(const float *xy, uint32_t color) {
229	    if (!(drawing || target_drawing)) return;
230	    vita2d_color_vertex *v = vita2d_pool_memalign(6 * sizeof(*v), 8);
231	    if (!v) return;
232	    const int corners[6] = {0, 1, 2, 0, 2, 3};
233	    for (int i = 0; i < 6; i++) {
234	        v[i].x = xy[corners[i] * 2];
235	        v[i].y = xy[corners[i] * 2 + 1];
236	        v[i].z = 0.5f;
237	        v[i].color = color;
238	    }
239	    batch_append(BATCH_COLOR, NULL, 0, 0, v, sizeof(*v));
240	}
241	void vita_gxm_clip(int enabled, int x, int y, int width, int height) {
242	    if (target_drawing) return; /* Offscreen targets draw unclipped. */
243	    if (enabled == clip_enabled_cache && (!enabled || (clip_rect_cache[0] == x && clip_rect_cache[1] == y &&
244	            clip_rect_cache[2] == width && clip_rect_cache[3] == height))) {
245	        return;
246	    }
247	    flush_batch();
248	    stat_clips++;
249	    clip_enabled_cache = enabled;
250	    clip_rect_cache[0] = x; clip_rect_cache[1] = y; clip_rect_cache[2] = width; clip_rect_cache[3] = height;
251	    if (enabled) {
252	        vita2d_set_clip_rectangle(x, y, x + width, y + height);
253	        vita2d_enable_clipping();
254	    } else {
255	        vita2d_disable_clipping();
256	    }
257	}
258	/* The GPU renders a frame while the CPU runs the next frame's scripts and
259	 * physics. Pool vertices and retired textures are only released once that
260	 * frame is done: at the start of the next frame, not right after submitting
261	 * it (R16 logs: 5-9 ms of CPU idle per frame waiting here). */
262	static void wait_gpu(void) {
263	    if (!gpu_pending) return;
264	    SceUInt64 wait_started = sceKernelGetProcessTimeWide();
265	    vita2d_wait_rendering_done();
266	    last_gpu_wait_us = (unsigned)(sceKernelGetProcessTimeWide() - wait_started);
267	    gpu_pending = 0;
268	    while (retired) {
269	        GXMTexture *t = retired;
270	        retired = t->next;
271	        destroy_texture(t);
272	    }
273	    vita2d_pool_reset();
274	}
275	void vita_gxm_end(int present) {
276	    if (!drawing) return;
277	    flush_batch();
278	    vita_gxm_scene3d_end();
279	    vita2d_disable_clipping();
280	    vita2d_end_drawing();
281	    if (present) vita2d_swap_buffers();
282	    gpu_pending = 1;
283	    drawing = 0;
284	    if (present) {
285	        SceUInt64 now = sceKernelGetProcessTimeWide();
286	        if (perf_last_end) perf_frame_us += now - perf_last_end;
287	        perf_last_end = now;
288	        perf_draws += stat_draws; perf_quads += stat_quads; perf_clips += stat_clips;
289	        perf_gpu_wait += last_gpu_wait_us;
290	        if (++perf_frames >= PERF_FRAMES) {
291	            fprintf(stderr, "[gxm2d-perf] frames=%u avg_frame_us=%llu fps=%.1f draws=%llu quads=%llu clips=%llu gpu_wait_us=%llu targets=%u\n",
292	                    perf_frames, perf_frame_us / perf_frames, perf_frame_us ? 1000000.0 * perf_frames / (double)perf_frame_us : 0.0,
293	                    perf_draws / perf_frames, perf_quads / perf_frames, perf_clips / perf_frames, perf_gpu_wait / perf_frames, stat_targets);
294	            fflush(stderr);
295	            perf_frames = 0; perf_draws = perf_quads = perf_clips = perf_gpu_wait = perf_frame_us = 0;
296	            stat_targets = 0;
297	        }
298	    }
299	    stat_draws = stat_quads = stat_clips = 0;
300	}
301	
302	/* Offscreen render targets (SubViewport). Drawn before the main scene of
303	 * the frame; the main scene waits on the fragment dependency. Coordinates
304	 * use the same 960x544 ortho space, mapped onto the target by the viewport. */
305	void *vita_gxm_target_create(int width, int height) {
306	    if (!initialized || width < 1 || height < 1 || width > 2048 || height > 2048) return NULL;
307	    GXMTexture *t = calloc(1, sizeof(*t));
308	    if (!t) return NULL;
309	    t->texture = vita2d_create_empty_texture_rendertarget(width, height, SCE_GXM_TEXTURE_FORMAT_A8B8G8R8);
310	    if (!t->texture) { free(t); return NULL; }
311	    t->bytes = vita_texture_allocation_bytes(width, height, 4);
312	    texture_bytes += t->bytes;
313	    return t;
314	}
315	int vita_gxm_target_begin(void *target, uint32_t clear_color) {
316	    GXMTexture *t = target;
317	    if (!initialized || !t || drawing || target_drawing) return 0;
318	    /* Targets are the first scene of a frame: release the previous one. */
319	    wait_gpu();
320	    vita2d_start_drawing_advanced(t->texture, SCE_GXM_SCENE_FRAGMENT_SET_DEPENDENCY);
321	    SceGxmContext *ctx = vita2d_get_context();
322	    float w = (float)vita2d_texture_get_width(t->texture), h = (float)vita2d_texture_get_height(t->texture);
323	    sceGxmSetViewport(ctx, w * 0.5f, w * 0.5f, h * 0.5f, -h * 0.5f, 0.5f, 0.5f);
324	    vita2d_disable_clipping();
325	    vita2d_set_clear_color(clear_color);
326	    vita2d_clear_screen();
327	    target_drawing = 1;
328	    stat_targets++;
329	    return 1;
330	}
331	void vita_gxm_target_end(void) {
332	    if (!target_drawing) return;
333	    flush_batch();
334	    vita2d_end_drawing();
335	    SceGxmContext *ctx = vita2d_get_context();
336	    sceGxmSetViewport(ctx, 480.0f, 480.0f, 272.0f, -272.0f, 0.5f, 0.5f);
337	    target_drawing = 0;
338	    target_dependency = 1;
339	}
340	void vita_gxm_finish(void) {
341	    if (!initialized) return;
342	    vita_gxm_end(0);
343	    wait_gpu();
344	    if (mesh_arena) { gpu_free(mesh_arena_uid); mesh_arena = NULL; mesh_arena_used = 0; }
345	    if (white_texture) { vita2d_free_texture(white_texture); white_texture = NULL; }
346	    vita2d_fini();
347	    initialized = 0;
348	}
349	/* Prototype reuses the pinned libvita2d vertex programs with a real MVP matrix.
350	 * Their shader computes homogeneous clip coordinates; GXM performs clipping,
351	 * perspective divide, interpolation and depth testing. This private symbol is
352	 * deliberately isolated here until a standalone GXM shader cache replaces it. */
353	extern float _vita2d_ortho_matrix[16];
354	void vita_gxm_scene3d_end(void) {
355	    if (!scene3d_drawing) return;
356	    flush_batch();
357	    memcpy(_vita2d_ortho_matrix, canvas_matrix, sizeof(canvas_matrix));
358	    SceGxmContext *ctx = vita2d_get_context();
359	    sceGxmSetFrontDepthFunc(ctx, SCE_GXM_DEPTH_FUNC_ALWAYS);
360	    sceGxmSetBackDepthFunc(ctx, SCE_GXM_DEPTH_FUNC_ALWAYS);
361	    sceGxmSetFrontDepthWriteEnable(ctx, SCE_GXM_DEPTH_WRITE_DISABLED);
362	    sceGxmSetBackDepthWriteEnable(ctx, SCE_GXM_DEPTH_WRITE_DISABLED);
363	    scene3d_drawing = 0;
364	}
365	static void begin_scene3d(void) {
366	    if (scene3d_drawing) return;
367	    SceGxmContext *ctx = vita2d_get_context();
368	    memcpy(canvas_matrix, _vita2d_ortho_matrix, sizeof(canvas_matrix));
369	    sceGxmSetViewport(ctx, 480.0f, 480.0f, 272.0f, -272.0f, 0.5f, 0.5f);
370	    sceGxmSetCullMode(ctx, SCE_GXM_CULL_NONE);
371	    sceGxmSetFrontDepthFunc(ctx, SCE_GXM_DEPTH_FUNC_LESS_EQUAL);
372	    sceGxmSetBackDepthFunc(ctx, SCE_GXM_DEPTH_FUNC_LESS_EQUAL);
373	    sceGxmSetFrontDepthWriteEnable(ctx, SCE_GXM_DEPTH_WRITE_ENABLED);
374	    sceGxmSetBackDepthWriteEnable(ctx, SCE_GXM_DEPTH_WRITE_ENABLED);
375	    scene3d_drawing = 1;
376	}
377	int vita_gxm_triangles3d(void *texture, const float *xyz, const float *uv, unsigned count, const float *mvp, uint32_t color) {
378	    if (!drawing || !scene3d_enabled || !xyz || !mvp || !count || count > 3072 || count % 3 || (texture && !uv)) return 0;
379	    void *vertices = vita2d_pool_memalign(count * (texture ? sizeof(vita2d_texture_vertex) : sizeof(vita2d_color_vertex)), 8);
380	    if (!vertices) return 0;
381	    flush_batch();
382	    begin_scene3d();
383	    memcpy(_vita2d_ortho_matrix, mvp, sizeof(canvas_matrix));
384	    if (texture) {
385	        GXMTexture *t = texture;
386	        vita2d_texture_vertex *v = vertices;
387	        for (unsigned i = 0; i < count; i++) {
388	            v[i].x = xyz[i*3]; v[i].y = xyz[i*3+1]; v[i].z = xyz[i*3+2];
389	            v[i].u = uv[i*2]; v[i].v = uv[i*2+1];
390	        }
391	        vita2d_texture_set_filters(t->texture, SCE_GXM_TEXTURE_FILTER_POINT, SCE_GXM_TEXTURE_FILTER_POINT);
392	        vita2d_draw_array_textured(t->texture, SCE_GXM_PRIMITIVE_TRIANGLES, v, count, color);
393	    } else {
394	        vita2d_color_vertex *v = vertices;
395	        for (unsigned i = 0; i < count; i++) {
396	            v[i].x = xyz[i*3]; v[i].y = xyz[i*3+1]; v[i].z = xyz[i*3+2]; v[i].color = color;
397	        }
398	        vita2d_draw_array(SCE_GXM_PRIMITIVE_TRIANGLES, v, count);
399	    }
400	    return 1;
401	}
402	void *vita_gxm_mesh_create(const float *xyz, const float *uv, unsigned count) {
403	    if (!initialized || !scene3d_enabled || !xyz || !count || count % 3 || mesh_arena_failed) return NULL;
404	    if (!mesh_arena) {
405	        mesh_arena = gpu_alloc(SCE_KERNEL_MEMBLOCK_TYPE_USER_RW_UNCACHE, MESH_ARENA_BYTES, 16,
406	                SCE_GXM_MEMORY_ATTRIB_READ, &mesh_arena_uid);
407	        if (!mesh_arena) {
408	            /* Keep the CPU path working when USER memory is short. */
409	            mesh_arena_failed = 1;
410	            fprintf(stderr, "[gxm3d] mesh arena allocation failed bytes=%u; using CPU vertex path\n", MESH_ARENA_BYTES);
411	            fflush(stderr);
412	            return NULL;
413	        }
414	        log_free_memory("mesh_arena");
415	    }
416	    unsigned bytes = (count * sizeof(vita2d_texture_vertex) + 15u) & ~15u;
417	    unsigned header = (sizeof(GXMMesh) + 15u) & ~15u;
418	    if (mesh_arena_used + header + bytes > MESH_ARENA_BYTES) return NULL;
419	    GXMMesh *mesh = (GXMMesh *)(mesh_arena + mesh_arena_used);
420	    mesh->vertices = (vita2d_texture_vertex *)(mesh_arena + mesh_arena_used + header);
421	    mesh->count = count;
422	    for (unsigned i = 0; i < count; i++) {
423	        vita2d_texture_vertex *v = &mesh->vertices[i];
424	        v->x = xyz[i * 3]; v->y = xyz[i * 3 + 1]; v->z = xyz[i * 3 + 2];
425	        v->u = uv ? uv[i * 2] : 0.0f; v->v = uv ? uv[i * 2 + 1] : 0.0f;
426	    }
427	    mesh_arena_used += header + bytes;
428	    return mesh;
429	}
430	int vita_gxm_mesh_draw(void *handle, void *texture, const float *mvp, uint32_t color) {
431	    GXMMesh *mesh = handle;
432	    if (!drawing || !scene3d_enabled || !mesh || !mvp) return 0;
433	    if (!texture && !white_texture) {
434	        white_texture = vita2d_create_empty_texture_format(8, 8, SCE_GXM_TEXTURE_FORMAT_A8B8G8R8);
435	        if (!white_texture) return 0;
436	        memset(vita2d_texture_get_datap(white_texture), 0xff, vita2d_texture_get_stride(white_texture) * 8);
437	    }
438	    vita2d_texture *t = texture ? ((GXMTexture *)texture)->texture : white_texture;
439	    flush_batch();
440	    begin_scene3d();
441	    memcpy(_vita2d_ortho_matrix, mvp, sizeof(canvas_matrix));
442	    vita2d_texture_set_filters(t, SCE_GXM_TEXTURE_FILTER_POINT, SCE_GXM_TEXTURE_FILTER_POINT);
443	    /* vita2d's linear index buffer holds 65535 entries. */
444	    for (unsigned offset = 0; offset < mesh->count; offset += 65532u) {
445	        unsigned batch = mesh->count - offset < 65532u ? mesh->count - offset : 65532u;
446	        vita2d_draw_array_textured(t, SCE_GXM_PRIMITIVE_TRIANGLES, mesh->vertices + offset, batch, color);
447	    }
448	    return 1;
449	}
450	void vita_gxm_mesh_reset(void) {
451	    mesh_arena_used = 0;
452	}
453	unsigned vita_gxm_mesh_arena_used(void) {
454	    return mesh_arena_used;
455	}
456	unsigned vita_gxm_last_gpu_wait_us(void) {
