462	/* Blended 3D overlays (decals) test depth but must not write it. */
463	void vita_gxm_depth_write(int enabled) {
464	    if (!drawing || !scene3d_enabled) return;
465	    begin_scene3d();
466	    SceGxmContext *ctx = vita2d_get_context();
467	    SceGxmDepthWriteMode mode = enabled ? SCE_GXM_DEPTH_WRITE_ENABLED : SCE_GXM_DEPTH_WRITE_DISABLED;
468	    sceGxmSetFrontDepthWriteEnable(ctx, mode);
469	    sceGxmSetBackDepthWriteEnable(ctx, mode);
470	}
471	/* Per-vertex lighting pass: vita2d's own color shaders, recompiled by the
472	 * shader patcher with a 2x multiply blend (dst = 2 * src * dst). The first
473	 * pass draws the albedo texture; this pass multiplies it by vertex colors
474	 * that store light / 2, so 0x80 leaves a pixel unchanged and 0xff doubles it. */
475	extern const SceGxmProgram color_v_gxp_start;
476	extern const SceGxmProgram color_f_gxp_start;
477	extern SceGxmVertexProgram *_vita2d_colorVertexProgram;
478	extern const SceGxmProgramParameter *_vita2d_colorWvpParam;
479	static SceGxmShaderPatcherId light_fragment_id;
480	static SceGxmFragmentProgram *light_fragment_program;
481	static int light_program_failed;
482	typedef struct GXMLightMesh {
483	    vita2d_color_vertex *vertices;
484	    unsigned count;
485	} GXMLightMesh;
486	static int ensure_light_program(void) {
487	    if (light_fragment_program) return 1;
488	    if (light_program_failed) return 0;
489	    SceGxmShaderPatcher *patcher = vita2d_get_shader_patcher();
490	    int err = patcher ? sceGxmShaderPatcherRegisterProgram(patcher, &color_f_gxp_start, &light_fragment_id) : -1;
491	    if (err >= 0) {
492	        static const SceGxmBlendInfo blend = {
493	            .colorMask = SCE_GXM_COLOR_MASK_ALL,
494	            .colorFunc = SCE_GXM_BLEND_FUNC_ADD,
495	            .alphaFunc = SCE_GXM_BLEND_FUNC_ADD,
496	            .colorSrc = SCE_GXM_BLEND_FACTOR_DST_COLOR,
497	            .colorDst = SCE_GXM_BLEND_FACTOR_SRC_COLOR,
498	            .alphaSrc = SCE_GXM_BLEND_FACTOR_ZERO,
499	            .alphaDst = SCE_GXM_BLEND_FACTOR_ONE,
500	        };
501	        err = sceGxmShaderPatcherCreateFragmentProgram(patcher, light_fragment_id,
502	                SCE_GXM_OUTPUT_REGISTER_FORMAT_UCHAR4, SCE_GXM_MULTISAMPLE_NONE,
503	                &blend, &color_v_gxp_start, &light_fragment_program);
504	    }
505	    fprintf(stderr, "[gxm3d] vertex lighting program rc=0x%08x\n", (unsigned)err);
506	    fflush(stderr);
507	    if (err < 0 || !light_fragment_program) {
508	        light_fragment_program = NULL;
509	        light_program_failed = 1;
510	        return 0;
511	    }
512	    return 1;
513	}
514	static void draw_light_vertices(const vita2d_color_vertex *vertices, unsigned count, const float *mvp) {
515	    SceGxmContext *ctx = vita2d_get_context();
516	    sceGxmSetVertexProgram(ctx, _vita2d_colorVertexProgram);
517	    sceGxmSetFragmentProgram(ctx, light_fragment_program);
518	    void *uniforms;
519	    sceGxmReserveVertexDefaultUniformBuffer(ctx, &uniforms);
520	    sceGxmSetUniformDataF(uniforms, _vita2d_colorWvpParam, 0, 16, mvp);
521	    for (unsigned offset = 0; offset < count; offset += 65532u) {
522	        unsigned batch = count - offset < 65532u ? count - offset : 65532u;
523	        sceGxmSetVertexStream(ctx, 0, vertices + offset);
524	        sceGxmDraw(ctx, SCE_GXM_PRIMITIVE_TRIANGLES, SCE_GXM_INDEX_FORMAT_U16, vita2d_get_linear_indices(), batch);
525	    }
526	}
527	int vita_gxm_vertex_lighting_available(void) {
528	    return initialized && scene3d_enabled && ensure_light_program();
529	}
530	void *vita_gxm_light_mesh_create(const float *xyz, unsigned count) {
531	    if (!mesh_arena || !xyz || !count || count % 3 || !ensure_light_program()) return NULL;
532	    unsigned bytes = (count * sizeof(vita2d_color_vertex) + 15u) & ~15u;
533	    unsigned header = (sizeof(GXMLightMesh) + 15u) & ~15u;
534	    if (mesh_arena_used + header + bytes > MESH_ARENA_BYTES) return NULL;
535	    GXMLightMesh *mesh = (GXMLightMesh *)(mesh_arena + mesh_arena_used);
536	    mesh->vertices = (vita2d_color_vertex *)(mesh_arena + mesh_arena_used + header);
537	    mesh->count = count;
538	    for (unsigned i = 0; i < count; i++) {
539	        vita2d_color_vertex *v = &mesh->vertices[i];
540	        v->x = xyz[i * 3]; v->y = xyz[i * 3 + 1]; v->z = xyz[i * 3 + 2];
541	        v->color = 0xff808080u;
542	    }
543	    mesh_arena_used += header + bytes;
544	    return mesh;
545	}
546	/* Called while the CPU builds a frame; vita_gxm_end waited for the GPU, so
547	 * the previous frame no longer reads these vertices. */
548	void vita_gxm_light_mesh_set_colors(void *handle, const uint32_t *colors) {
549	    GXMLightMesh *mesh = handle;
550	    if (!mesh || !colors) return;
551	    for (unsigned i = 0; i < mesh->count; i++) mesh->vertices[i].color = colors[i];
552	}
553	int vita_gxm_light_mesh_draw(void *handle, const float *mvp) {
554	    GXMLightMesh *mesh = handle;
555	    if (!drawing || !mesh || !mvp || !ensure_light_program()) return 0;
556	    begin_scene3d();
557	    draw_light_vertices(mesh->vertices, mesh->count, mvp);
558	    return 1;
559	}
560	/* Additive blending for glows and flares (the original shader uses blend_add). */
561	void vita_gxm_blend_add(int enabled) {
562	    vita2d_set_blend_mode_add(enabled ? 1 : 0);
563	}
