1	// Native GXM canvas renderer. Included by rasterizer_gxm_vita.cpp after
2	// GXMTextureStorage. Every primitive is lowered to the two bridge calls the
3	// loader already exports (flat and textured quads), so this file needs no
4	// new loader symbols. Triangles are sent as quads with a repeated vertex.
5	
6	class GXMCanvas : public RasterizerCanvasDummy {
7	    GXMTextureStorage *storage;
8	    unsigned int logged_rects = 0;
9	
10	    struct PolygonData {
11	        Vector<int> indices;
12	        Vector<Vector2> points;
13	        Vector<Color> colors;
14	        Vector<Vector2> uvs;
15	    };
16	    HashMap<PolygonID, PolygonData> polygons;
17	    PolygonID next_polygon = 1;
18	
19	    // Per-call state shared by the helpers below.
20	    float scale_x = 1, scale_y = 1, offset_x = 0, offset_y = 0;
21	    bool snap = false;
22	    // CPU time spent walking and lowering canvas items, logged every 300 calls.
23	    uint64_t perf_canvas_us = 0;
24	    unsigned perf_items = 0, perf_calls = 0;
25	
26	    Vector2 to_screen(const Transform2D &xf, const Vector2 &p, bool p_snap) const {
27	        Vector2 s = xf.xform(p);
28	        if (p_snap) s = s.floor();
29	        return Vector2(offset_x + s.x * scale_x, offset_y + s.y * scale_y);
30	    }
31	
32	    struct Tex {
33	        void *gpu = nullptr;
34	        Size2 size;
35	        bool linear = false;
36	    };
37	
38	    // Consecutive commands mostly use the same texture (tiles, glyphs, UI
39	    // atlas). Each full resolve costs several RID hash lookups, so the last
40	    // result is reused within one canvas_render_items call.
41	    RID cached_rid;
42	    int cached_filter = -1;
43	    bool cached_ok = false;
44	    Tex cached_tex;
45	
46	    bool resolve_texture(RID texture, const Item *item, RSE::CanvasItemTextureFilter default_filter, Tex &r_tex) {
47	        if (!texture.is_valid()) return true; // Untextured: flat color.
48	        const int filter_key = int(item->texture_filter) * 16 + int(default_filter);
49	        if (texture == cached_rid && filter_key == cached_filter) {
50	            r_tex = cached_tex;
51	            return cached_ok;
52	        }
53	        cached_rid = texture;
54	        cached_filter = filter_key;
55	        cached_ok = resolve_texture_uncached(texture, item, default_filter, cached_tex);
56	        r_tex = cached_tex;
57	        return cached_ok;
58	    }
59	
60	    bool resolve_texture_uncached(RID texture, const Item *item, RSE::CanvasItemTextureFilter default_filter, Tex &r_tex) {
61	        r_tex = Tex();
62	        r_tex.size = storage->texture_size_with_proxy(texture);
63	        if (r_tex.size.x <= 0 || r_tex.size.y <= 0) return false;
64	        r_tex.gpu = storage->get_gpu(texture);
65	        if (!r_tex.gpu) return false;
66	        auto filter = item->texture_filter == RSE::CANVAS_ITEM_TEXTURE_FILTER_DEFAULT ? default_filter : item->texture_filter;
67	        filter = storage->texture_filter(texture, filter);
68	        r_tex.linear = filter != RSE::CANVAS_ITEM_TEXTURE_FILTER_NEAREST && filter != RSE::CANVAS_ITEM_TEXTURE_FILTER_NEAREST_WITH_MIPMAPS;
69	        return true;
70	    }
71	
72	    // Screen-space quad (4 corners in winding order) with normalized UVs.
73	    void emit_quad(const Tex &tex, const Vector2 *s, const Vector2 *uv, const Color &color) {
74	        float xy[8], st[8];
75	        for (int i = 0; i < 4; i++) {
76	            xy[2 * i] = s[i].x; xy[2 * i + 1] = s[i].y;
77	            st[2 * i] = uv ? uv[i].x : 0.0f; st[2 * i + 1] = uv ? uv[i].y : 0.0f;
78	        }
79	        if (tex.gpu) {
80	            vita_gxm_texture_quad(tex.gpu, xy, st, gxm_color(color), tex.linear);
81	        } else {
82	            vita_gxm_quad(xy, gxm_color(color));
83	        }
84	    }
85	
86	    void emit_triangle(const Tex &tex, const Vector2 *s, const Vector2 *uv, const Color &color) {
87	        const Vector2 q[4] = { s[0], s[1], s[2], s[2] };
88	        if (uv) {
89	            const Vector2 quv[4] = { uv[0], uv[1], uv[2], uv[2] };
90	            emit_quad(tex, q, quv, color);
91	        } else {
92	            emit_quad(tex, q, nullptr, color);
93	        }
94	    }
95	
96	    // Local-space axis-aligned rectangle with a pixel-space source region.
97	    void emit_rect(const Tex &tex, const Transform2D &xf, const Rect2 &dst, const Rect2 &src, const Color &color) {
98	        if (dst.size.x == 0 || dst.size.y == 0) return;
99	        const Vector2 p[4] = { dst.position, dst.position + Vector2(dst.size.x, 0), dst.position + dst.size, dst.position + Vector2(0, dst.size.y) };
100	        Vector2 s[4];
101	        for (int i = 0; i < 4; i++) s[i] = to_screen(xf, p[i], snap);
102	        if (!tex.gpu) {
103	            emit_quad(tex, s, nullptr, color);
104	            return;
105	        }
106	        const Vector2 a = src.position / tex.size, b = (src.position + src.size) / tex.size;
107	        const Vector2 uv[4] = { a, Vector2(b.x, a.y), b, Vector2(a.x, b.y) };
108	        emit_quad(tex, s, uv, color);
109	    }
110	
111	    // Lines are one canvas pixel wide (scaled with the viewport).
112	    void emit_line(const Tex &tex, const Transform2D &xf, const Vector2 &a, const Vector2 &b, const Color &color) {
113	        Vector2 sa = to_screen(xf, a, false), sb = to_screen(xf, b, false);
114	        Vector2 d = sb - sa;
115	        float len = d.length();
116	        if (len < 0.001f) {
117	            d = Vector2(1, 0);
118	        } else {
119	            d /= len;
120	        }
121	        const float half = MAX(scale_x, 1.0f) * 0.5f;
122	        Vector2 n = Vector2(-d.y, d.x) * half;
123	        const Vector2 s[4] = { sa + n, sb + n, sb - n, sa - n };
124	        emit_quad(tex, s, nullptr, color);
125	    }
126	
127	    static Color average(const Color *c, int n) {
128	        Color r(0, 0, 0, 0);
129	        for (int i = 0; i < n; i++) r += c[i];
130	        return r / float(n);
131	    }
132	
133	    void draw_rect_command(const Item *item, const Item::CommandRect *rect, const Transform2D &xf, const Color &modulate,
134	            RSE::CanvasItemTextureFilter default_filter) {
135	        if (rect->flags & (CANVAS_RECT_MSDF | CANVAS_RECT_LCD)) {
136	            WARN_PRINT_ONCE("GXM: MSDF and LCD rectangles are not implemented.");
137	            return;
138	        }
139	        Color color = rect->modulate * item->final_modulate * modulate;
140	        Tex tex;
141	        if (!resolve_texture(rect->texture, item, default_filter, tex)) return;
142	        if (!tex.gpu) {
143	            emit_rect(tex, xf, rect->rect, Rect2(), color);
144	            return;
145	        }
146	        Rect2 src = (rect->flags & CANVAS_RECT_REGION) ? rect->source : Rect2(Vector2(), tex.size);
147	        if (item->material.is_valid() && storage->is_render_target_texture(rect->texture)) {
148	            // A viewport shown through a material is the magnifier lens: its
149	            // shader keeps the inscribed circle, emulated here as a fan.
150	            draw_ellipse(tex, xf, rect->rect, src, color);
151	            return;
152	        }
153	        if (rect->flags & CANVAS_RECT_TILE) {
154	            draw_tiled(tex, xf, rect->rect, src, color);
155	            return;
156	        }
157	        Vector2 points[4] = { rect->rect.position, rect->rect.position + Vector2(rect->rect.size.x, 0),
158	                rect->rect.position + rect->rect.size, rect->rect.position + Vector2(0, rect->rect.size.y) };
159	        Vector2 s[4], uv[4];
160	        const Vector2 corners[4] = { Vector2(0, 0), Vector2(1, 0), Vector2(1, 1), Vector2(0, 1) };
161	        for (int i = 0; i < 4; i++) {
162	            s[i] = to_screen(xf, points[i], snap);
163	            Vector2 c = corners[i];
164	            if (rect->flags & CANVAS_RECT_TRANSPOSE) SWAP(c.x, c.y);
165	            if (rect->flags & CANVAS_RECT_FLIP_H) c.x = 1.0f - c.x;
166	            if (rect->flags & CANVAS_RECT_FLIP_V) c.y = 1.0f - c.y;
167	            uv[i] = (src.position + c * src.size) / tex.size;
168	        }
169	        emit_quad(tex, s, uv, color);
170	        if (logged_rects++ < 3) {
171	            fprintf(stderr, "[gxm2d] rect submitted xy=(%.1f,%.1f) rgba=%08lx\n", s[0].x, s[0].y, (unsigned long)gxm_color(color));
172	            fflush(stderr);
173	        }
174	    }
175	
176	    void draw_ellipse(const Tex &tex, const Transform2D &xf, const Rect2 &dst, const Rect2 &src, const Color &color) {
177	        static const int SEGMENTS = 40;
178	        const Vector2 center = dst.get_center(), radius = dst.size * 0.5f;
179	        const Vector2 uv_center = (src.position + src.size * 0.5f) / tex.size, uv_radius = src.size * 0.5f / tex.size;
180	        Vector2 prev_s, prev_uv;
181	        for (int k = 0; k <= SEGMENTS; k++) {
182	            const float a = Math::TAU * k / SEGMENTS;
183	            const Vector2 dir(Math::cos(a), Math::sin(a));
184	            const Vector2 p_s = to_screen(xf, center + dir * radius, false), p_uv = uv_center + dir * uv_radius;
185	            if (k > 0) {
186	                const Vector2 tri[3] = { to_screen(xf, center, false), prev_s, p_s };
187	                const Vector2 uv[3] = { uv_center, prev_uv, p_uv };
188	                emit_triangle(tex, tri, uv, color);
189	            }
190	            prev_s = p_s;
191	            prev_uv = p_uv;
192	        }
193	    }
194	
195	    // Texture repeat without sampler wrap: split the source region at
196	    // texture-cell boundaries. Capped so a huge repeat cannot stall a frame.
197	    void draw_tiled(const Tex &tex, const Transform2D &xf, const Rect2 &dst, const Rect2 &src, const Color &color) {
198	        if (src.size.x <= 0 || src.size.y <= 0) return;
199	        const Vector2 ratio = dst.size / src.size;
200	        int pieces = 0;
201	        for (float y = src.position.y; y < src.position.y + src.size.y - 0.001f;) {
202	            float cell_y = Math::floor(y / tex.size.y) * tex.size.y;
203	            float y_end = MIN(cell_y + tex.size.y, src.position.y + src.size.y);
204	            for (float x = src.position.x; x < src.position.x + src.size.x - 0.001f;) {
205	                float cell_x = Math::floor(x / tex.size.x) * tex.size.x;
206	                float x_end = MIN(cell_x + tex.size.x, src.position.x + src.size.x);
207	                Rect2 piece(Vector2(x - cell_x, y - cell_y), Vector2(x_end - x, y_end - y));
208	                Rect2 out(dst.position + (Vector2(x, y) - src.position) * ratio, piece.size * ratio);
209	                emit_rect(tex, xf, out, piece, color);
210	                if (++pieces >= 1024) return;
211	                x = x_end;
212	            }
213	            y = y_end;
214	        }
215	    }
216	
217	    void draw_ninepatch(const Item *item, const Item::CommandNinePatch *np, const Transform2D &xf, const Color &modulate,
218	            RSE::CanvasItemTextureFilter default_filter) {
219	        Color color = np->color * item->final_modulate * modulate;
220	        Tex tex;
221	        if (!resolve_texture(np->texture, item, default_filter, tex)) return;
222	        const Rect2 &r = np->rect;
223	        Rect2 src = np->source;
224	        if (tex.gpu && (src.size.x == 0 || src.size.y == 0)) src = Rect2(Vector2(), tex.size);
225	        // Margins are in source pixels and keep that size on screen (SIDE_LEFT, TOP, RIGHT, BOTTOM).
226	        float ml = np->margin[SIDE_LEFT], mt = np->margin[SIDE_TOP], mr = np->margin[SIDE_RIGHT], mb = np->margin[SIDE_BOTTOM];
227	        // Shrink margins proportionally when the rectangle is smaller than them.
228	        if (ml + mr > r.size.x && ml + mr > 0) { float k = r.size.x / (ml + mr); ml *= k; mr *= k; }
229	        if (mt + mb > r.size.y && mt + mb > 0) { float k = r.size.y / (mt + mb); mt *= k; mb *= k; }
230	        const float dx[4] = { r.position.x, r.position.x + ml, r.position.x + r.size.x - mr, r.position.x + r.size.x };
231	        const float dy[4] = { r.position.y, r.position.y + mt, r.position.y + r.size.y - mb, r.position.y + r.size.y };
232	        const float sml = np->margin[SIDE_LEFT], smt = np->margin[SIDE_TOP], smr = np->margin[SIDE_RIGHT], smb = np->margin[SIDE_BOTTOM];
233	        const float sx[4] = { src.position.x, src.position.x + sml, src.position.x + src.size.x - smr, src.position.x + src.size.x };
234	        const float sy[4] = { src.position.y, src.position.y + smt, src.position.y + src.size.y - smb, src.position.y + src.size.y };
235	        for (int j = 0; j < 3; j++) {
236	            for (int i = 0; i < 3; i++) {
237	                if (i == 1 && j == 1 && !np->draw_center) continue;
238	                Rect2 d(dx[i], dy[j], dx[i + 1] - dx[i], dy[j + 1] - dy[j]);
239	                if (d.size.x <= 0 || d.size.y <= 0) continue;
240	                Rect2 s(sx[i], sy[j], sx[i + 1] - sx[i], sy[j + 1] - sy[j]);
241	                if (tex.gpu && (s.size.x <= 0 || s.size.y <= 0)) continue;
242	                if (!tex.gpu) {
243	                    emit_rect(tex, xf, d, s, color);
244	                    continue;
245	                }
246	                // The middle column/row follows the axis mode; corners never tile.
247	                emit_patch_cell(np->texture, tex, xf, d, s, color, i == 1 ? np->axis_x : RSE::NINE_PATCH_STRETCH,
248	                        j == 1 ? np->axis_y : RSE::NINE_PATCH_STRETCH);
249	            }
250	        }
251	    }
252	
253	    // Tiled nine-patch cells used to cost one quad per repeat (a 600 px panel
254	    // over a 6 px pattern is ~100 quads per row). The cell's source region is
255	    // copied once into a "sheet" texture holding it repeated kx * ky times, so
256	    // each sheet-sized piece of the cell is a single quad.
257	    struct TileSheet {
258	        void *gpu = nullptr;
259	        Size2 size;
260	        Vector2i repeats;
261	    };
262	    HashMap<String, TileSheet> tile_sheets;
263	    static const int SHEET_TARGET = 128;
264	
265	    const TileSheet *tile_sheet(RID texture, const Rect2 &src, bool tile_x, bool tile_y) {
266	        const Rect2i region(src);
267	        if (region.size.x < 1 || region.size.y < 1) return nullptr;
268	        const String key = itos(texture.get_id()) + ":" + itos(region.position.x) + "," + itos(region.position.y) + "," +
269	                itos(region.size.x) + "," + itos(region.size.y) + ":" + itos(tile_x) + itos(tile_y);
270	        const TileSheet *cached = tile_sheets.getptr(key);
271	        if (cached) return cached->gpu ? cached : nullptr;
272	        if (tile_sheets.size() >= 256) {
273	            for (KeyValue<String, TileSheet> &entry : tile_sheets) {
274	                vita_gxm_texture_free(entry.value.gpu);
275	            }
276	            tile_sheets.clear();
277	        }
278	        TileSheet sheet;
279	        Ref<Image> image = storage->texture_2d_get(texture);
280	        if (image.is_valid() && Rect2i(Vector2i(), image->get_size()).encloses(region)) {
281	            Ref<Image> cell = image->get_region(region);
282	            cell->convert(Image::FORMAT_RGBA8);
283	            sheet.repeats = Vector2i(tile_x ? MAX(1, SHEET_TARGET / region.size.x) : 1, tile_y ? MAX(1, SHEET_TARGET / region.size.y) : 1);
284	            const Vector2i sheet_size = region.size * sheet.repeats;
285	            Ref<Image> out = Image::create_empty(sheet_size.x, sheet_size.y, false, Image::FORMAT_RGBA8);
286	            for (int y = 0; y < sheet.repeats.y; y++) {
287	                for (int x = 0; x < sheet.repeats.x; x++) {
288	                    out->blit_rect(cell, Rect2i(Vector2i(), region.size), Vector2i(x, y) * region.size);
289	                }
290	            }
291	            sheet.gpu = vita_gxm_texture_create(sheet_size.x, sheet_size.y, out->get_data().ptr());
292	            sheet.size = Size2(sheet_size);
293	        }
294	        tile_sheets.insert(key, sheet); // A failed sheet is remembered as null.
295	        cached = tile_sheets.getptr(key);
296	        return cached->gpu ? cached : nullptr;
297	    }
298	
299	    // Splits one axis of a tiled cell into pieces of at most `per_piece` tiles.
300	    // Returns the piece count; d_len/s_len are destination and source lengths.
301	    static int tile_pieces(float dst, float src, RSE::NinePatchAxisMode mode, int per_piece, float *d_off, float *d_len, float *s_len, int max_pieces) {
302	        if (mode == RSE::NINE_PATCH_STRETCH || src <= 0.0f || dst <= src) {
303	            d_off[0] = 0; d_len[0] = dst; s_len[0] = src;
304	            return 1;
305	        }
306	        // TILE cuts the last tile; TILE_FIT scales whole tiles to fill exactly.
307	        float tiles = dst / src, scale = 1.0f;
308	        if (mode == RSE::NINE_PATCH_TILE_FIT) {
309	            tiles = MAX(1.0f, Math::round(tiles));
310	            scale = dst / (tiles * src);
311	        }
312	        int n = 0;
313	        float offset = 0;
314	        for (float remaining = tiles; remaining > 0.001f && n < max_pieces; n++) {
315	            const float t = MIN((float)per_piece, remaining);
316	            d_off[n] = offset; d_len[n] = t * src * scale; s_len[n] = t * src;
317	            offset += d_len[n];
318	            remaining -= t;
319	        }
320	        return n;
321	    }
322	
323	    void emit_patch_cell(RID texture, const Tex &tex, const Transform2D &xf, const Rect2 &d, const Rect2 &s, const Color &color,
324	            RSE::NinePatchAxisMode mode_x, RSE::NinePatchAxisMode mode_y) {
325	        static const int MAX_PIECES = 256;
326	        const bool tile_x = mode_x != RSE::NINE_PATCH_STRETCH && d.size.x > s.size.x;
327	        const bool tile_y = mode_y != RSE::NINE_PATCH_STRETCH && d.size.y > s.size.y;
328	        Tex draw = tex;
329	        Vector2i per_piece(1, 1);
330	        Vector2 origin = s.position;
331	        if (tile_x || tile_y) {
332	            const TileSheet *sheet = tile_sheet(texture, s, tile_x, tile_y);
333	            if (sheet) {
334	                draw.gpu = sheet->gpu;
335	                draw.size = sheet->size;
336	                per_piece = sheet->repeats;
337	                origin = Vector2();
338	            }
339	        }
340	        float xo[MAX_PIECES], xl[MAX_PIECES], xs[MAX_PIECES], yo[MAX_PIECES], yl[MAX_PIECES], ys[MAX_PIECES];
341	        const int nx = tile_pieces(d.size.x, s.size.x, tile_x ? mode_x : RSE::NINE_PATCH_STRETCH, per_piece.x, xo, xl, xs, MAX_PIECES);
342	        int ny = tile_pieces(d.size.y, s.size.y, tile_y ? mode_y : RSE::NINE_PATCH_STRETCH, per_piece.y, yo, yl, ys, MAX_PIECES);
343	        if (nx * ny > 4096) {
344	            // Keep the vertex pool safe: stretch the second axis instead.
345	            ny = tile_pieces(d.size.y, s.size.y, RSE::NINE_PATCH_STRETCH, 1, yo, yl, ys, MAX_PIECES);
346	        }
347	        for (int y = 0; y < ny; y++) {
348	            for (int x = 0; x < nx; x++) {
349	                emit_rect(draw, xf, Rect2(d.position.x + xo[x], d.position.y + yo[y], xl[x], yl[y]),
350	                        Rect2(origin, Vector2(xs[x], ys[y])), color);
351	            }
352	        }
353	    }
354	
355	    void draw_vertices(const Tex &tex, const Transform2D &xf, RSE::PrimitiveType primitive, const Vector2 *points, const Color *colors,
356	            bool per_vertex_color, const Color &base, const Vector2 *uvs, const int *indices, int count) {
357	        auto idx = [&](int i) { return indices ? indices[i] : i; };
358	        auto col = [&](int i) { return per_vertex_color ? colors[idx(i)] * base : base; };
359	        switch (primitive) {
360	            case RSE::PRIMITIVE_TRIANGLES:
361	            case RSE::PRIMITIVE_TRIANGLE_STRIP: {
362	                const bool strip = primitive == RSE::PRIMITIVE_TRIANGLE_STRIP;
363	                const int tris = strip ? count - 2 : count / 3;
364	                for (int t = 0; t < tris; t++) {
365	                    int k[3] = { strip ? t : t * 3, strip ? t + 1 : t * 3 + 1, strip ? t + 2 : t * 3 + 2 };
366	                    Vector2 s[3], uv[3];
367	                    Color c[3];
368	                    for (int v = 0; v < 3; v++) {
369	                        s[v] = to_screen(xf, points[idx(k[v])], false);
370	                        if (uvs) uv[v] = uvs[idx(k[v])];
371	                        c[v] = col(k[v]);
372	                    }
373	                    Color avg = average(c, 3);
374	                    if (avg.a <= 0.002f) continue;
375	                    emit_triangle(tex, s, uvs ? uv : nullptr, avg);
376	                }
377	            } break;
378	            case RSE::PRIMITIVE_LINES:
379	                for (int i = 0; i + 1 < count; i += 2) {
380	                    emit_line(Tex(), xf, points[idx(i)], points[idx(i + 1)], (col(i) + col(i + 1)) * 0.5f);
381	                }
382	                break;
383	            case RSE::PRIMITIVE_LINE_STRIP:
384	                for (int i = 0; i + 1 < count; i++) {
385	                    emit_line(Tex(), xf, points[idx(i)], points[idx(i + 1)], (col(i) + col(i + 1)) * 0.5f);
386	                }
387	                break;
388	            case RSE::PRIMITIVE_POINTS:
389	                for (int i = 0; i < count; i++) {
390	                    Vector2 p = points[idx(i)];
391	                    emit_rect(Tex(), xf, Rect2(p - Vector2(0.5f, 0.5f), Vector2(1, 1)), Rect2(), col(i));
392	                }
393	                break;
394	            default:
395	                break;
396	        }
397	    }
398	
399	    void draw_polygon(const Item *item, const Item::CommandPolygon *cmd, const Transform2D &xf, const Color &modulate,
400	            RSE::CanvasItemTextureFilter default_filter) {
401	        const PolygonData *p = polygons.getptr(cmd->polygon.polygon_id);
402	        if (!p || p->points.is_empty()) return;
403	        Tex tex;
404	        if (!resolve_texture(cmd->texture, item, default_filter, tex)) return;
405	        const Color base = item->final_modulate * modulate;
406	        const int point_count = p->points.size();
407	        const bool per_vertex = p->colors.size() == point_count;
408	        const Color single = (!per_vertex && p->colors.size() >= 1) ? p->colors[0] * base : base;
409	        const bool has_uv = tex.gpu && p->uvs.size() == point_count;
410	        const int count = p->indices.is_empty() ? point_count : p->indices.size();
411	        draw_vertices(tex, xf, cmd->primitive, p->points.ptr(), per_vertex ? p->colors.ptr() : nullptr, per_vertex,
412	                per_vertex ? base : single, has_uv ? p->uvs.ptr() : nullptr, p->indices.is_empty() ? nullptr : p->indices.ptr(), count);
413	    }
414	
415	    void draw_primitive(const Item *item, const Item::CommandPrimitive *cmd, const Transform2D &xf, const Color &modulate,
416	            RSE::CanvasItemTextureFilter default_filter) {
417	        Tex tex;
418	        if (!resolve_texture(cmd->texture, item, default_filter, tex)) return;
419	        const Color base = item->final_modulate * modulate;
420	        switch (cmd->point_count) {
421	            case 1:
422	                draw_vertices(tex, xf, RSE::PRIMITIVE_POINTS, cmd->points, cmd->colors, true, base, nullptr, nullptr, 1);
423	                break;
424	            case 2:
425	                draw_vertices(tex, xf, RSE::PRIMITIVE_LINES, cmd->points, cmd->colors, true, base, nullptr, nullptr, 2);
426	                break;
427	            case 3:
428	                draw_vertices(tex, xf, RSE::PRIMITIVE_TRIANGLES, cmd->points, cmd->colors, true, base, tex.gpu ? cmd->uvs : nullptr, nullptr, 3);
429	                break;
430	            case 4: {
431	                static const int quad[6] = { 0, 1, 2, 0, 2, 3 };
432	                draw_vertices(tex, xf, RSE::PRIMITIVE_TRIANGLES, cmd->points, cmd->colors, true, base, tex.gpu ? cmd->uvs : nullptr, quad, 6);
433	            } break;
434	            default:
435	                break;
436	        }
437	    }
438	
439	public:
440	    explicit GXMCanvas(GXMTextureStorage *p_storage) : storage(p_storage) {}
441	
442	    PolygonID request_polygon(const Vector<int> &p_indices, const Vector<Point2> &p_points, const Vector<Color> &p_colors,
443	            const Vector<Point2> &p_uvs = Vector<Point2>(), const Vector<int> &p_bones = Vector<int>(),
444	            const Vector<float> &p_weights = Vector<float>(), int p_count = -1) override {
445	        PolygonData data;
446	        data.indices = p_indices;
447	        if (p_count >= 0 && p_count < data.indices.size()) data.indices.resize(p_count);
448	        // Drop out-of-range indices once here instead of checking every frame.
449	        for (int i = 0; i < data.indices.size(); i++) {
450	            if (data.indices[i] < 0 || data.indices[i] >= p_points.size()) {
451	                data.indices.clear();
452	                break;
453	            }
454	        }
455	        data.points = p_points;
456	        data.colors = p_colors;
457	        data.uvs = p_uvs;
458	        PolygonID id = next_polygon++;
459	        polygons.insert(id, data);
460	        return id;
461	    }
462	    void free_polygon(PolygonID p_polygon) override { polygons.erase(p_polygon); }
463	
464	    void canvas_render_items(RID target, Item *items, const Color &modulate, Light *, Light *,
465	            const Transform2D &, RSE::CanvasItemTextureFilter default_filter, RSE::CanvasItemTextureRepeat,
466	            bool p_snap, bool &sdf_used, RenderingServerTypes::RenderInfo * = nullptr) override {
467	        sdf_used = false;
468	        // Vita has a single physical scanout, but the main Godot scene is not
469	        // guaranteed to own the first RenderingServer render target. A strict
470	        // RID/960x544 guard used to discard *all* menu items (quads=0, cmds=0).
471	        // Render any canvas target with items directly to the native screen.
472	        // This is the Vita-specific offscreen viewport fallback, not full
473	        // multi-viewport compositing.
474	        if (!items) return;
475	        const Size2i target_size = storage->render_target_get_size(target);
476	        scale_x = target_size.x > 0 ? 960.0f / (float)target_size.x : 1.0f;
477	        scale_y = target_size.y > 0 ? 544.0f / (float)target_size.y : 1.0f;
478	        offset_x = 0;
479	        offset_y = 0;
480	        snap = p_snap;
481	        cached_rid = RID(); // Textures may have been freed since the last call.
482	        // Any target other than the screen is a SubViewport: render it into
483	        // its own GXM texture (the viewport maps the 960x544 space onto it).
484	        const bool offscreen = !storage->is_screen(target);
485	        if (offscreen) {
486	            void *gpu = storage->target_gpu(target);
487	            if (!gpu) return;
488	            if (!vita_gxm_target_begin(gpu, gxm_color(storage->render_target_get_clear_request_color(target)))) {
489	                WARN_PRINT_ONCE("GXM: offscreen viewport skipped (main scene already started).");
490	                return;
491	            }
492	            storage->render_target_disable_clear_request(target);
493	        } else if (bool(ProjectSettings::get_singleton()->get_setting("rendering/vita/keep_aspect", false))) {
494	            scale_x = scale_y = MIN(scale_x, scale_y);
495	            offset_x = (960 - target_size.x * scale_x) * 0.5f;
496	            offset_y = (544 - target_size.y * scale_y) * 0.5f;
497	        }
498	        static unsigned canvas_calls = 0;
499	        if (canvas_calls++ < 12) {
500	            fprintf(stderr, "[gxm2d] canvas target=%llu screen=%d viewport=%dx%d native=960x544 items=1 scale=(%.3f,%.3f)\n",
501	                    (unsigned long long)target.get_id(), storage->is_screen(target),
502	                    target_size.x, target_size.y, scale_x, scale_y);
503	            fflush(stderr);
504	        }
505	        if (!offscreen) {
506	            vita_gxm_begin(gxm_color(storage->render_target_get_clear_request_color(target)));
507	            storage->render_target_disable_clear_request(target);
508	        }
509	        const uint64_t started_us = OS::get_singleton()->get_ticks_usec();
510	        const double now = double(started_us) / 1000000.0;
511	        for (Item *item = items; item; item = item->next) {
512	            if (item->material.is_valid() || (item->material_owner && item->material_owner->material.is_valid()) || item->canvas_group_owner) {
513	                // Shader/material effects are unsupported, but discarding the
514	                // whole item makes normal sprites invisible. Draw the unshaded
515	                // command as a fallback; transparencies still use vertex tint.
516	                WARN_PRINT_ONCE("GXM: drawing canvas item without unsupported material/group effects.");
517	            }
518	            Rect2i clip = item->final_clip_owner ? Rect2i(item->final_clip_owner->final_clip_rect) : Rect2i();
519	            if (item->final_clip_owner && !clip.has_area()) continue;
520	            auto apply_clip = [&](bool enabled) {
521	                vita_gxm_clip(enabled,
522	                        (int)(offset_x + clip.position.x * scale_x), (int)(offset_y + clip.position.y * scale_y),
523	                        (int)(clip.size.x * scale_x), (int)(clip.size.y * scale_y));
524	            };
525	            apply_clip(item->final_clip_owner != nullptr);
526	            Transform2D extra;
527	            bool skipping = false;
528	            for (Item::Command *command = item->commands; command; command = command->next) {
529	                if (command->type == Item::Command::TYPE_TRANSFORM) {
530	                    extra = static_cast<Item::CommandTransform *>(command)->xform;
531	                    continue;
532	                }
533	                if (command->type == Item::Command::TYPE_ANIMATION_SLICE) {
534	                    // Animated tiles: only the frame whose slice holds the current time is drawn.
535	                    const Item::CommandAnimationSlice *as = static_cast<Item::CommandAnimationSlice *>(command);
536	                    if (as->animation_length > 0) {
537	                        double local = Math::fposmod(now - as->offset, as->animation_length);
538	                        skipping = !(local >= as->slice_begin && local < as->slice_end);
539	                    } else {
540	                        skipping = false;
541	                    }
542	                    continue;
543	                }
544	                if (skipping) continue;
545	                if (command->type == Item::Command::TYPE_CLIP_IGNORE) {
546	                    const bool ignore = static_cast<Item::CommandClipIgnore *>(command)->ignore;
547	                    apply_clip(!ignore && item->final_clip_owner != nullptr);
548	                    continue;
549	                }
550	                const Transform2D xf = item->final_transform * extra;
551	                switch (command->type) {
552	                    case Item::Command::TYPE_RECT:
553	                        draw_rect_command(item, static_cast<Item::CommandRect *>(command), xf, modulate, default_filter);
554	                        break;
555	                    case Item::Command::TYPE_NINEPATCH:
556	                        draw_ninepatch(item, static_cast<Item::CommandNinePatch *>(command), xf, modulate, default_filter);
557	                        break;
558	                    case Item::Command::TYPE_POLYGON:
559	                        draw_polygon(item, static_cast<Item::CommandPolygon *>(command), xf, modulate, default_filter);
560	                        break;
561	                    case Item::Command::TYPE_PRIMITIVE:
562	                        draw_primitive(item, static_cast<Item::CommandPrimitive *>(command), xf, modulate, default_filter);
563	                        break;
564	                    default:
565	                        WARN_PRINT_ONCE("GXM: mesh, multimesh and particle canvas commands are not implemented.");
566	                        break;
567	                }
568	            }
569	        }
570	        for (Item *item = items; item; item = item->next) perf_items++;
571	        perf_canvas_us += OS::get_singleton()->get_ticks_usec() - started_us;
572	        if (++perf_calls >= 300) {
573	            fprintf(stderr, "[gxm2d-canvas] calls=%u avg_canvas_us=%llu avg_items=%u\n", perf_calls,
574	                    (unsigned long long)(perf_canvas_us / perf_calls), perf_items / perf_calls);
575	            fflush(stderr);
576	            perf_calls = perf_items = 0;
577	            perf_canvas_us = 0;
578	        }
579	        if (offscreen) {
580	            vita_gxm_target_end();
581	        } else {
582	            vita_gxm_clip(0, 0, 0, 0, 0);
583	        }
584	    }
585	};
