 23	    };
 24	    HashMap<RID, RID> rt_textures; // texture RID -> render target RID
 25	    mutable RID_Owner<Target> targets;
 26	    RID screen;
 27	    struct Texture {
 28	        Ref<Image> image;
 29	        Image::Format format = Image::FORMAT_MAX;
 30	        Size2i size;
 31	        void *gpu = nullptr;
 32	        unsigned long long failed_epoch = ~0ULL;
 33	        bool has_alpha = false;
 34	    };
 35	    struct CanvasTexture {
 36	        RID diffuse;
 37	        RSE::CanvasItemTextureFilter filter = RSE::CANVAS_ITEM_TEXTURE_FILTER_DEFAULT;
 38	    };
 39	    HashMap<RID, Texture> textures;
 40	    HashMap<RID, RID> proxies;
 41	    HashMap<RID, CanvasTexture> canvas_textures;
 42	    unsigned long long allocation_epoch = 0;
 43	public:
 44	    void release_gpu() {
 45	        for (KeyValue<RID, Texture> &entry : textures) {
 46	            vita_gxm_texture_free(entry.value.gpu);
 47	            entry.value.gpu = nullptr;
 48	        }
 49	    }
 50	    RID resolve(RID rid) const {
 51	        for (int i = 0; i < 16; i++) {
 52	            const CanvasTexture *ct = canvas_textures.getptr(rid);
 53	            if (ct) { rid = ct->diffuse; continue; }
 54	            const RID *proxy = proxies.getptr(rid);
 55	            if (proxy) { rid = *proxy; continue; }
 56	            return rid;
 57	        }
 58	        return RID(); // Invalid/cyclic proxy chain.
 59	    }
 60	    void texture_2d_initialize(RID rid, const Ref<Image> &image) override {
 61	        ERR_FAIL_COND(!owns_texture(rid) || image.is_null() || image->is_empty());
 62	        Ref<Image> rgba = image->duplicate();
 63	        if (rgba->is_compressed()) {
 64	            ERR_FAIL_COND_MSG(rgba->decompress() != OK, "GXM: image decompression failed.");
 65	        }
 66	        rgba->convert(Image::FORMAT_RGBA8);
 67	        Texture *old = textures.getptr(rid);
 68	        if (old && old->gpu) {
 69	            vita_gxm_texture_free(old->gpu);
 70	            allocation_epoch++;
 71	        }
 72	        Texture t;
 73	        t.image = rgba;
 74	        t.format = image->get_format();
 75	        t.size = Size2i(image->get_width(), image->get_height());
 76	        // Cut-out and blended textures skip the multiplicative lighting pass,
 77	        // which would also darken whatever shows through their holes.
 78	        t.has_alpha = rgba->detect_alpha() != Image::ALPHA_NONE;
 79	        textures.insert(rid, t);
 80	    }
 81	    void texture_2d_update(RID rid, const Ref<Image> &image, int layer = 0) override {
 82	        ERR_FAIL_COND(layer != 0);
 83	        texture_2d_initialize(rid, image);
 84	    }
 85	    Ref<Image> texture_2d_get(RID rid) const override {
 86	        const Texture *t = textures.getptr(resolve(rid));
 87	        return t ? t->image : Ref<Image>();
 88	    }
 89	    Image::Format texture_get_format(RID rid) const override {
 90	        const Texture *t = textures.getptr(resolve(rid));
 91	        return t ? t->format : Image::FORMAT_MAX;
 92	    }
 93	    Size2 texture_size_with_proxy(RID rid) override {
 94	        RID base = resolve(rid);
 95	        const RID *target = rt_textures.getptr(base);
 96	        if (target) {
 97	            const Target *rt = targets.get_or_null(*target);
 98	            return rt ? Size2(rt->size) : Size2();
 99	        }
100	        const Texture *t = textures.getptr(base);
101	        return t ? Size2(t->size) : Size2();
102	    }
103	    bool is_render_target_texture(RID rid) const { return rt_textures.has(resolve(rid)); }
104	    // GPU surface of an offscreen target, (re)created to match its size.
105	    void *target_gpu(RID rid) {
106	        Target *t = targets.get_or_null(rid);
107	        if (!t || t->size.x < 1 || t->size.y < 1) return nullptr;
108	        if (t->gpu && t->gpu_size != t->size) {
109	            vita_gxm_texture_free(t->gpu);
110	            t->gpu = nullptr;
111	        }
112	        if (!t->gpu) {
113	            t->gpu = vita_gxm_target_create(t->size.x, t->size.y);
114	            t->gpu_size = t->size;
115	            fprintf(stderr, "[gxm2d] offscreen target %dx%d %s\n", t->size.x, t->size.y, t->gpu ? "created" : "FAILED");
116	            fflush(stderr);
117	        }
118	        return t->gpu;
119	    }
120	    RID render_target_get_texture(RID rid) override {
121	        Target *t = targets.get_or_null(rid);
122	        ERR_FAIL_NULL_V(t, RID());
123	        if (t->texture.is_null()) {
124	            t->texture = texture_allocate();
125	            rt_textures.insert(t->texture, rid);
126	        }
127	        return t->texture;
128	    }
129	    void texture_set_size_override(RID rid, int width, int height) override {
130	        Texture *t = textures.getptr(resolve(rid));
131	        if (t) t->size = Size2i(width, height);
132	    }
133	    void texture_proxy_initialize(RID rid, RID base) override {
134	        ERR_FAIL_COND(rid == base || !owns_texture(rid));
135	        proxies.insert(rid, base);
136	    }
137	    void texture_proxy_update(RID rid, RID base) override { texture_proxy_initialize(rid, base); }
138	    void texture_free(RID rid) override {
139	        Texture *t = textures.getptr(rid);
140	        if (t && t->gpu) {
141	            vita_gxm_texture_free(t->gpu);
142	            allocation_epoch++;
143	        }
144	        textures.erase(rid);
145	        proxies.erase(rid);
146	        canvas_textures.erase(rid);
147	        if (rt_textures.has(rid)) {
148	            // Owned by its render target; released in render_target_free.
149	            return;
150	        }
151	        RendererDummy::TextureStorage::texture_free(rid);
152	    }
