154	        ERR_FAIL_COND(rid == by || !owns_texture(rid) || !owns_texture(by));
155	        Texture *source = textures.getptr(by);
156	        ERR_FAIL_NULL(source);
157	        Texture moved = *source;
158	        Texture *old = textures.getptr(rid);
159	        if (old) vita_gxm_texture_free(old->gpu);
160	        textures.erase(by);
161	        textures.insert(rid, moved);
162	        proxies.erase(rid);
163	        texture_free(by);
164	    }
165	    RID canvas_texture_allocate() override {
166	        RID rid = texture_allocate();
167	        canvas_textures.insert(rid, CanvasTexture());
168	        return rid;
169	    }
