171	    void canvas_texture_set_channel(RID rid, RSE::CanvasTextureChannel channel, RID texture) override {
172	        CanvasTexture *ct = canvas_textures.getptr(rid);
173	        ERR_FAIL_NULL(ct);
174	        if (channel == RSE::CANVAS_TEXTURE_CHANNEL_DIFFUSE) ct->diffuse = texture;
175	    }
