177	        CanvasTexture *ct = canvas_textures.getptr(rid);
178	        if (ct) ct->filter = filter;
179	    }
180	    RSE::CanvasItemTextureFilter texture_filter(RID rid, RSE::CanvasItemTextureFilter fallback) const {
181	        const CanvasTexture *ct = canvas_textures.getptr(rid);
182	        return ct && ct->filter != RSE::CANVAS_ITEM_TEXTURE_FILTER_DEFAULT ? ct->filter : fallback;
183	    }
184	    bool texture_has_alpha(RID rid) const {
185	        const Texture *t = textures.getptr(resolve(rid));
186	        return t && t->has_alpha;
187	    }
