    10		VITA_PROF_PROCESS, // SceneTree::process (scripts, animation, UI).
    11		VITA_PROF_PHYSICS_SCRIPTS, // SceneTree::physics_process.
    12		VITA_PROF_NAVIGATION,
    13		VITA_PROF_PHYSICS_3D,
    14		VITA_PROF_PHYSICS_2D,
    15		VITA_PROF_RENDER, // RenderingServer::draw (cull + GXM submit + present).
    16		VITA_PROF_ANIMATION, // AnimationMixer::_process_animation.
    17		VITA_PROF_SKELETON, // Skeleton3D pose updates.
    18		VITA_PROF_AUDIO3D, // AudioStreamPlayer3D panning and area queries.
    19		VITA_PROF_MAX
    20	};
