    27		explicit VitaProfScope(int p_slot) :
    28				slot(p_slot), start(OS::get_singleton()->get_ticks_usec()) {}
    29		~VitaProfScope() { vita_prof_us[slot] += OS::get_singleton()->get_ticks_usec() - start; }
