   349	void RasterizerGXMVita::set_boot_image_with_stretch(const Ref<Image> &p_image, const Color &p_color, RSE::SplashStretchMode p_stretch_mode, bool p_use_filter) {
   350	    vita_gxm_begin(gxm_color(Color(p_color.r, p_color.g, p_color.b, 1.0f)));
   351	    void *texture = nullptr;
   352	    if (p_image.is_valid() && !p_image->is_empty() && p_image->get_width() > 1) {
   353	        Ref<Image> image = p_image->duplicate();
   354	        if (image->is_compressed()) image->decompress();
   355	        image->convert(Image::FORMAT_RGBA8);
   356	        const Vector2 size(image->get_width(), image->get_height());
   357	        texture = vita_gxm_texture_create(image->get_width(), image->get_height(), image->get_data().ptr());
   358	        if (texture) {
   359	            float scale = MIN(960.0f / size.x, 544.0f / size.y);
   360	            if (p_stretch_mode == RSE::SPLASH_STRETCH_MODE_DISABLED) {
   361	                scale = MIN(scale, 1.0f);
   362	            } else if (!p_use_filter && scale >= 1.0f) {
   363	                scale = Math::floor(scale); // Pixel art: whole-pixel scaling.
   364	            }
   365	            const Vector2 extent = size * scale, origin = (Vector2(960, 544) - extent) * 0.5f;
   366	            const float xy[8] = { origin.x, origin.y, origin.x + extent.x, origin.y, origin.x + extent.x, origin.y + extent.y, origin.x, origin.y + extent.y };
   367	            const float uv[8] = { 0, 0, 1, 0, 1, 1, 0, 1 };
   368	            vita_gxm_texture_quad(texture, xy, uv, 0xffffffff, p_use_filter);
   369	        }
   370	    }
   371	    vita_gxm_end(1);
   372	    if (texture) vita_gxm_texture_free(texture);
   373	    fprintf(stderr, "[gxm2d] boot splash shown image=%dx%d\n", p_image.is_valid() ? p_image->get_width() : 0, p_image.is_valid() ? p_image->get_height() : 0);
   374	    fflush(stderr);
   375	}
