432	static int d_prim_array(void *c, const char *name, int prim, const uint8_t *data, uint32_t count) {
433		DecCtx *d = (DecCtx *)c;
434		Variant out;
435		int n = (int)count;
436		switch (prim) {
437			case MSG_PRIM_U8: {
438				PackedByteArray a;
439				a.resize(n);
440				if (n) memcpy(a.ptrw(), data, n);
441				out = a;
442			} break;
443			case MSG_PRIM_F32: {
444				PackedFloat32Array a;
445				a.resize(n);
446				if (n) memcpy(a.ptrw(), data, (size_t)n * 4);
447				out = a;
448			} break;
449			case MSG_PRIM_F64: {
450				PackedFloat64Array a;
451				a.resize(n);
452				if (n) memcpy(a.ptrw(), data, (size_t)n * 8);
453				out = a;
454			} break;
455			case MSG_PRIM_I32: {
456				PackedInt32Array a;
457				a.resize(n);
458				if (n) memcpy(a.ptrw(), data, (size_t)n * 4);
459				out = a;
460			} break;
461			case MSG_PRIM_I64:
462			case MSG_PRIM_U64:
463			case MSG_PRIM_U32: {
464				int sz = prim == MSG_PRIM_U32 ? 4 : 8;
465				PackedInt64Array a;
466				a.resize(n);
467				for (int i = 0; i < n; i++) a.write[i] = (int64_t)_ld(data + (size_t)i * sz, sz);
468				out = a;
469			} break;
470			case MSG_PRIM_BOOL: {
471				Array a;
472				for (int i = 0; i < n; i++) a.push_back(data[i] != 0);
473				out = a;
474			} break;
475			default: { // I8, U16, I16
476				int sz = msg_prim_size((msg_prim)prim);
477				PackedInt32Array a;
478				a.resize(n);
479				for (int i = 0; i < n; i++) {
480					uint64_t raw = _ld(data + (size_t)i * sz, sz);
481					a.write[i] = prim == MSG_PRIM_I8 ? (int8_t)raw : prim == MSG_PRIM_I16 ? (int16_t)raw : (int32_t)(uint16_t)raw;
482				}
483				out = a;
484			} break;
485		}
486		d->stack.write[d->stack.size() - 1].msg->set_member(StringName(String::utf8(name)), out);
487		return 0;
488	}
