518		int rc = msg_schema_decode(&schema, type_idx, p_payload.ptr(), p_payload.size(), &vis, &ctx, nullptr);
519		if (rc != MSG_SCHEMA_OK || ctx.root.is_null()) {
520			return rc == MSG_SCHEMA_ERR_TRUNCATED ? ERR_FILE_EOF : ERR_PARSE_ERROR;
521		}
522		// El decoder construyó un árbol nuevo: se adopta su contenido (el RosMsg actual
523		// conserva su identidad, como exige el patrón "reutilizar el mensaje" de rclgd).
524		members = ctx.root->members;
525		return OK;
526	}
